using CustomerManagement.API.Models;
using Microsoft.EntityFrameworkCore;

namespace CustomerManagement.API.Data;

/// <summary>Original Vietnamese demo episodes, added once to the local Development database.</summary>
public static class SampleLibrarySeeder
{
    private sealed record EpisodeSeed(int Chapter, string ChapterTitle, int Episode, string Title, string Content);
    private sealed record StorySeed(string Title, EpisodeSeed[] Episodes);

    private static readonly StorySeed[] Stories =
    [
        new("Tiệm sách ở cuối con hẻm", [
            E(1, "Cơn mưa đầu mùa", 2, "Chiếc ô để quên", "Chiếc ô màu xanh nằm nghiêng bên kệ văn học, còn đọng những giọt nước tròn như hạt thủy tinh. Lan Chi nhận ra nó thuộc về người khách đã ghé tiệm vào chiều qua, người mua một cuốn sách không hỏi giá và để lại lời nhắn rằng mình sẽ quay lại.\n\nCô đặt chiếc ô cạnh cửa, tự nhủ chỉ cần chờ đến hết buổi. Nhưng khi mưa rơi trở lại, tiếng chuông ngoài hiên vẫn im lìm. Trong cuốn sổ cũ của mẹ, Chi tìm thấy một dòng chữ lạ: “Nếu ai để quên thứ gì, hãy giữ lại cả lý do họ muốn quay về.”"),
            E(1, "Cơn mưa đầu mùa", 3, "Ngăn kéo dưới quầy", "Một buổi sáng, chiếc ngăn kéo vốn kẹt cứng bỗng mở ra khi Chi đặt cuốn sách không tên lên mặt gỗ. Bên trong là những tấm vé xem phim, một chiếc cúc áo và hàng chục mẩu giấy ghi tên người trong hẻm. Mỗi cái tên đều được nối với một cuốn sách mà mẹ cô từng cho mượn.\n\nChi bắt đầu đi tìm những người ấy. Có người đã chuyển nhà, có người không còn nhớ tiệm sách, nhưng ai cũng giữ một trang giấy nhỏ với nét chữ quen thuộc. Hóa ra mẹ cô không chỉ cho mượn sách; bà còn âm thầm lưu lại những điều người ta chưa đủ can đảm nói thành lời."),
            E(2, "Cuốn sách không có tên", 2, "Trang giấy bị xé", "Cuốn sách trống cuối cùng có một vết rách ở gáy. Chi đem nó ra cửa sổ, lần theo mép giấy và nhận ra một trang đã bị xé rất cẩn thận. Phía trong bìa còn dấu chì mờ, như thể ai đó từng viết rồi cố xóa đi.\n\nNgười đóng sách già ở đầu phố nói loại giấy này được đặt riêng cho mẹ cô nhiều năm trước. Ông nhớ bà thường mang theo hai bản giống hệt nhau, nhưng chỉ đem một bản về tiệm. Chi nhìn chiếc ô xanh vẫn chưa có chủ, chợt hiểu rằng có người đang cất giữ nửa còn lại của câu chuyện."),
            E(2, "Cuốn sách không có tên", 3, "Mùi giấy và tên người", "Một cậu bé tên Bảo bước vào tiệm, xin tìm cuốn sách mà bà ngoại từng đọc cho cậu nghe. Cậu chỉ nhớ mùi giấy cũ và một đoạn về con đường đầy đèn lồng. Chi đưa cậu qua từng kệ, kiên nhẫn để cậu chạm vào những gáy sách đã bạc màu.\n\nKhi cậu chọn đúng cuốn sách không tên, bên trong rơi ra tấm ảnh của mẹ Chi cùng một cô gái trẻ. Sau ảnh là hai cái tên viết cạnh nhau, một cái đã quen, cái còn lại là tên bà ngoại của Bảo. Người khách hôm mưa có thể đang tìm chính cuốn sách này."),
            E(3, "Người khách lúc năm giờ", 2, "Giờ mở cửa đặc biệt", "Chi treo một tấm bảng nhỏ: từ năm đến sáu giờ, ai cũng có thể mang về một cuốn sách mà chưa cần trả lời vì sao mình chọn nó. Buổi đầu chỉ có bác thợ khóa ghé qua. Bác chọn truyện phiêu lưu, rồi đứng rất lâu ngoài hiên như đang đợi ai.\n\nNhững ngày sau, con hẻm bắt đầu có thêm tiếng bước chân vào giờ ấy. Mỗi người để lại một câu chuyện ngắn trong ngăn kéo dưới quầy. Chi không hỏi tên; cô chỉ xếp chúng vào cuốn sổ của mẹ, nơi những khoảng trống dường như đang dần được lấp đầy."),
            E(3, "Người khách lúc năm giờ", 3, "Hẹn nhau dưới mái hiên", "Người khách mang chiếc ô xanh quay lại vào đúng năm giờ, nhưng lần này anh không vào tiệm ngay. Anh đứng dưới mái hiên, nhìn tấm bảng mới và đọc những câu chuyện đã được viết thêm. Chi nhận ra anh trong bức ảnh cũ: người đứng cạnh mẹ cô, trẻ hơn nhiều và nụ cười vẫn vậy.\n\nAnh kể rằng cuốn sách không tên vốn là món quà mẹ cô chuẩn bị cho một người bạn đã rời thành phố. Cơn mưa năm ấy khiến lời hẹn lỡ mất. Chi đặt hai bản sách cạnh nhau, khép lại quãng chờ đợi kéo dài và mở cửa tiệm rộng hơn cho những người còn muốn quay về."),
            E(4, "Những câu chuyện ở lại", 1, "Danh sách người mượn", "Sau ngày người khách quay về, Lan Chi tìm thấy trong ngăn kéo một danh sách người từng mượn sách suốt ba mươi năm. Có những cái tên được gạch nhẹ, có tên bên cạnh lời nhắn “đã trả vào mùa hạ”. Cô cùng Bảo đi qua con hẻm, trao lại từng cuốn sách cho những gia đình còn nhớ.\n\nMột số người không muốn nhận sách; họ muốn kể vì sao mình từng cần nó. Chi ghi lời kể vào cuốn sổ mới, để mỗi cuốn sách có thêm một nơi nó đã đi qua. Tiệm sách dần giống một trạm dừng nhỏ, nơi ai cũng có thể để lại dấu vết rồi tiếp tục hành trình."),
            E(4, "Những câu chuyện ở lại", 2, "Chiếc kệ cạnh cửa", "Bảo đề nghị dành chiếc kệ cạnh cửa cho sách của những người trong hẻm. Mỗi cuốn có một mảnh giấy ghi ai gửi và ai được đọc tiếp, nhưng không bắt buộc người mượn phải ghi tên. Chi sợ sách sẽ thất lạc; bác thợ khóa bảo những thứ được chuyền tay bằng lòng tin thường quay về đúng lúc.\n\nĐến cuối tuần, chiếc kệ đã đầy. Có sách nấu ăn, truyện trinh thám và một cuốn sổ tay trồng rau của người bán hoa. Chi không còn phải đoán cuốn sách không tên thuộc về ai. Cô đặt nó ở giữa kệ, mở trang đầu tiên cho người tiếp theo tự viết."),
            E(4, "Những câu chuyện ở lại", 3, "Một trang để viết tiếp", "Ngày mưa trở lại, tiệm sách đông hơn mọi chiều trong tháng. Người khách năm giờ mang tới một cuốn sổ mới, còn Bảo đem theo tấm ảnh đã được phục chế. Trong ảnh, mẹ Chi và người bạn cũ đứng dưới mái hiên, mỗi người cầm một nửa chiếc ô xanh.\n\nChi dán ảnh lên bức tường sau quầy, bên cạnh tấm bảng mời mọi người viết tiếp câu chuyện của mình. Cô hiểu tiệm sách không cần giữ tất cả mọi người ở lại; chỉ cần để họ biết nơi này vẫn sáng đèn. Ngoài hẻm, chiếc chuông cửa khẽ ngân khi một vị khách mới bước vào." )
        ]),
        new("Bản đồ những vì sao", [
            E(1, "Tấm bản đồ trên gác mái", 2, "Mực bạc dưới ánh đèn", "Mai đặt tấm bản đồ gần ngọn đèn dầu, và những đường mực vốn vô hình dần hiện lên như các nhánh sông bạc. Ở góc giấy có ký hiệu của bảy ngọn đồi, nhưng bản đồ chỉ đánh dấu sáu. Cô nhớ lời ông ngoại: nơi không được vẽ mới là nơi cần tìm nhất.\n\nKhải mang kính thiên văn lên gác mái, so các chòm sao với những dấu chấm trên giấy. Một ngôi sao nằm lệch khỏi mọi bảng thiên văn hiện đại. Khi họ tính lại vị trí, điểm lệch ấy rơi đúng vào thung lũng đã bị xóa khỏi bản đồ thị trấn."),
            E(1, "Tấm bản đồ trên gác mái", 3, "Mật mã của người vẽ", "Sau khung tranh cũ, hai người tìm thấy mảnh giấy ghi những con số không theo thứ tự. Mai nhận ra chúng trùng với ngày sinh của các nhà thiên văn từng làm việc ở đài quan sát bỏ hoang. Mỗi con số dẫn tới một ký hiệu mới trên tấm bản đồ.\n\nHọ giải được câu đầu tiên: “Đừng đi theo ngôi sao sáng nhất.” Câu ấy buộc Khải phải bỏ chiếc la bàn quen thuộc và tin vào những điểm tối giữa các chòm sao. Mặt sau giấy còn một nét bút chì mang chữ ký của mẹ Mai, người cô tưởng chưa từng đặt chân lên gác mái này."),
            E(2, "Lối đi qua rừng bạc", 2, "Dấu chân giữa sương", "Rừng bạc chỉ xuất hiện khi sương phủ kín lối mòn. Cây cối phản chiếu ánh trăng đến mức Mai không phân biệt được đường thật và bóng của nó. Khải buộc một sợi chỉ đỏ vào cành đầu tiên, nhưng khi họ ngoảnh lại, sợi chỉ đã nằm ở phía trước.\n\nMột đàn đom đóm nhỏ bay thành hình mũi tên, dừng lại trên phiến đá có ký hiệu y hệt bản đồ. Bên dưới phiến đá là chiếc hộp chống nước chứa ghi chép của người thám hiểm trước họ. Dòng cuối cùng viết rằng rừng không đổi đường; chính người đi bộ đang nhìn nó từ một hướng khác."),
            E(2, "Lối đi qua rừng bạc", 3, "Người canh lối", "Ở bìa rừng, họ gặp bà lão đan giỏ bằng những sợi cỏ phát sáng. Bà nhận ra dấu mực trên tay Mai và gọi cô bằng tên mẹ. Bà kể từng dẫn mẹ cô tới đây, nhưng mẹ Mai quay lại một mình vì không muốn biến bí mật thành món hàng cho những nhà sưu tầm.\n\nBà trao cho Khải một mảnh kim loại khắc tọa độ, rồi dặn rằng chỉ người đi cùng nhau mới nhìn thấy lối thứ hai. Khi Mai và Khải nắm chung hai đầu tấm bản đồ, con đường hiện ra giữa những thân cây, lặng lẽ như một lời mời."),
            E(3, "Ngôi sao thứ bảy", 2, "Bầu trời không tên", "Đài quan sát cũ phủ đầy bụi, nhưng chiếc kính lớn vẫn xoay được. Qua thấu kính, Mai thấy một chấm sáng đứng yên giữa nền trời đang chuyển động. Khải ghi lại vị trí, còn cô phát hiện nó không nằm ngoài không gian mà phản chiếu từ một mặt hồ dưới thung lũng.\n\nTại bờ hồ, tấm bản đồ khớp với bầu trời trên mặt nước. Ngôi sao thứ bảy mở ra một khoảng ký ức: những người từng sống ở thung lũng hiện lên trong ánh sáng xanh. Họ không để lại kho báu; họ để lại tên mình để nơi này không bị xóa thêm lần nữa."),
            E(3, "Ngôi sao thứ bảy", 3, "Nơi bản đồ kết thúc", "Khi bình minh lên, những dấu mực trên bản đồ nhạt dần, chỉ còn lại hình ngôi sao thứ bảy ở giữa. Mai chụp lại từng đường nét trước khi chúng biến mất. Khải đề nghị đưa bản đồ tới bảo tàng, nhưng cô muốn hỏi những gia đình trong thung lũng trước.\n\nHọ trở về với một danh sách dài những cái tên và lời kể. Mỗi người nhớ một phần khác nhau, không ai sở hữu toàn bộ câu chuyện. Mai hiểu tấm bản đồ không phải đường dẫn đến một nơi bí mật; nó là cách để những người đã bị quên có thể cùng trở lại trên bầu trời của mình."),
            E(4, "Những người vẽ bầu trời", 1, "Bức tường ở trường cũ", "Các gia đình trong thung lũng đề nghị vẽ lại bản đồ trên bức tường trường học bỏ trống. Mai mang ảnh chụp những nét mực đã phai, Khải đặt kính thiên văn ngoài sân để lũ trẻ có thể tìm ngôi sao thứ bảy. Mỗi gia đình chọn một ngọn đồi và kể tên người từng sống ở đó.\n\nBức tường không giống bản đồ trong bảo tàng: nó có thêm những con đường nhỏ, vườn cây và cả một cây cầu chưa từng được ghi trên giấy. Mai để trống một khoảng giữa tường, không phải vì thiếu dữ liệu, mà để người đến sau còn chỗ bổ sung điều mình nhớ."),
            E(4, "Những người vẽ bầu trời", 2, "Đài quan sát mở cửa", "Khải sửa lại mái đài quan sát và biến gian phòng chính thành nơi học thiên văn mỗi tối thứ bảy. Bà lão ở rừng bạc mang tới chiếc hộp ghi chép, còn Mai sắp những trang nhật ký theo từng thế hệ. Lần đầu tiên, câu chuyện về thung lũng không còn nằm trong tay một nhà sưu tầm.\n\nMột cậu bé hỏi liệu ngôi sao thứ bảy có thật hay chỉ là hình phản chiếu của hồ. Mai đưa kính cho cậu tự nhìn, rồi bảo cả hai cách hiểu đều có thể cùng tồn tại. Cậu ghi câu hỏi lên bảng, bên cạnh những câu hỏi chưa ai trả lời."),
            E(4, "Những người vẽ bầu trời", 3, "Tọa độ dành cho ngày mai", "Trước ngày rời thung lũng, Mai và Khải đặt một tấm bản đồ mới trong đài quan sát. Bản đồ ghi rõ điều đã xác minh và đánh dấu riêng những câu chuyện chỉ được truyền miệng. Không ai bị buộc phải chọn một phiên bản duy nhất.\n\nĐêm đó, họ cùng trẻ con ngắm mưa sao băng. Ngôi sao thứ bảy vẫn đứng yên trên mặt hồ, còn trên bức tường trường cũ, những nét vẽ mới nối các ngọn đồi với nhau. Mai cất tấm bản đồ ban đầu vào tủ kính, để lại bên cạnh nó một cây bút chì và một lời mời viết tiếp.")
        ]),
        new("Mùa mưa trên mái ngói", [
            E(1, "Chuyến tàu trễ giờ", 2, "Sân ga sau cơn giông", "Chuyến tàu vừa rời ga thì cơn mưa kéo tới, để lại Minh và Hạ dưới mái che dột một góc. Họ chưa từng gặp nhau, nhưng cùng nhận ra trên tay đối phương là vé tàu bị nhòe mực, ghi cùng một điểm đến đã bị xóa khỏi lịch trình từ nhiều năm trước.\n\nNgười soát vé nói tuyến ấy không còn hoạt động. Dẫu vậy, trên bảng điện tử cũ, một dòng chữ chớp lên trong đúng ba giây: “Chuyến cuối, sân số bốn.” Hạ giữ lại chiếc vé của mẹ, còn Minh mang theo lá thư chưa từng gửi. Có lẽ hai món đồ ấy đang dẫn họ tới cùng một ký ức."),
            E(1, "Chuyến tàu trễ giờ", 3, "Ghế cạnh cửa sổ", "Trên chuyến tàu đêm, Minh chọn ghế cạnh cửa sổ vì đó là chỗ ghi trên mặt sau lá thư. Hạ ngồi đối diện, cẩn thận vuốt phẳng tấm vé đã sờn. Ngoài trời chỉ có những mái nhà tối, nhưng trong kính cửa sổ họ thoáng thấy một con phố sáng đèn đang chạy ngược chiều đoàn tàu.\n\nMột bà cụ ngồi cuối toa nhận ra tên ga cũ trên vé. Bà kể nơi ấy từng có một khu phố ngập nước, nơi người ta gửi thư cho nhau qua những con thuyền giấy. Khi tàu giảm tốc giữa cánh đồng, bà đưa họ một chiếc chìa khóa và bảo hãy tìm căn nhà có mái ngói màu xanh."),
            E(2, "Một chiếc ô màu xanh", 2, "Nước mưa trên hiên", "Chiếc ô xanh được treo trên cột hiên một ngôi nhà khóa kín. Minh nhận ra chữ cái đầu tên mẹ mình khắc dưới cán ô, còn Hạ tìm thấy một vết xước giống hệt trên chiếc ô cũ của gia đình. Hai người hiểu món đồ này đã qua tay nhiều người trước khi trở lại đây.\n\nNgười hàng xóm kể chủ căn nhà từng che mưa cho những đứa trẻ đi học bằng xe đạp. Họ không để lại tài sản, chỉ để một quyển sổ ghi ai đang cần giúp. Hạ mở quyển sổ ở trang cuối và thấy tên mình, viết bằng nét chữ của một người cô chưa từng gặp."),
            E(2, "Một chiếc ô màu xanh", 3, "Những mái nhà cùng sáng", "Mưa làm mái ngói cũ rò nước, và Minh cùng Hạ phải chạy lên gác để đặt chậu hứng. Trên xà nhà có một dãy dấu mực xanh, mỗi dấu nối với tên một gia đình từng sống ở đây. Họ mang chậu đi khắp phố, hỏi thăm những người còn nhớ.\n\nĐến tối, từng ô cửa bật sáng. Hàng xóm kéo tới sửa mái nhà, mang theo thang, đinh và những câu chuyện cũ. Hạ nhận ra chiếc ô xanh không thuộc về một người; nó từng được chuyền tay mỗi mùa mưa. Cô đặt nó ở cửa, để người tiếp theo có thể mang đi."),
            E(3, "Lá thư chưa gửi", 2, "Địa chỉ ở mặt sau", "Lá thư đã phai gần hết, nhưng phía sau còn một địa chỉ viết bằng bút chì. Minh dẫn Hạ tới căn nhà nhỏ cạnh đường ray, nơi một người đàn ông lớn tuổi đang chăm mấy chậu hoa. Ông đọc tên người nhận rồi im lặng rất lâu: đó là em gái ông, người đã rời thành phố sau một trận lũ.\n\nHọ không mở lá thư. Minh trao nó cho ông, để ông tự quyết định có muốn đọc hay không. Ông đặt thư cạnh tách trà và nói sẽ gửi đi vào sáng mai, dù địa chỉ có thể đã đổi. Hạ nhìn mưa rơi trên mái ngói, lần đầu thấy một lời chưa nói vẫn có thể tìm được đường về."),
            E(3, "Lá thư chưa gửi", 3, "Ngày trời quang", "Sáng hôm sau, bầu trời trong xanh và con đường trước nhà ga khô ráo. Minh nhận được tin nhắn rằng lá thư đã được gửi qua bưu điện, còn Hạ tìm thấy một tấm bưu thiếp hồi âm trong hộp thư chung của khu phố. Không có lời giải thích dài dòng, chỉ có dòng chữ: “Tôi vẫn nhớ mái hiên ấy.”\n\nHọ quay lại sân ga số bốn, nơi chuyến tàu cũ không còn dừng nữa. Hạ cất vé vào sổ, Minh gấp chiếc ô xanh đặt ngay ngắn bên cửa. Mùa mưa kết thúc, nhưng khu phố đã có một thói quen mới: mỗi khi ai đi xa, hàng xóm cùng ra tiễn dưới mái hiên."),
            E(4, "Mái hiên chung", 1, "Sửa mái trước mùa gió", "Sau cơn mưa cuối mùa, Minh và Hạ thấy mái hiên nhà ga bị bật mất một tấm ngói. Họ rủ những người trong khu phố tới sửa trước khi gió lớn quay lại. Người thợ mộc mang thang, bà cụ trên tàu đem trà nóng, còn lũ trẻ nhặt những mảnh ngói vỡ thành một đống riêng.\n\nTrong lúc làm, mọi người phát hiện bên dưới xà gỗ có khắc tên những người từng góp tiền dựng mái hiên. Hạ chép lại từng cái tên vào sổ ga, để những người qua lại biết nơi trú mưa này đã được nhiều thế hệ cùng dựng nên."),
            E(4, "Mái hiên chung", 2, "Cuốn sổ chuyến đi", "Người soát vé cũ trao cho Minh một cuốn sổ ghi những chuyến tàu từng ghé sân số bốn. Mỗi trang có tên một hành khách, nhưng nhiều dòng bị bỏ trống ở cột điểm đến. Minh hỏi tại sao; ông bảo có người lên tàu mà chưa biết mình muốn đi đâu.\n\nHạ đề nghị mở cuốn sổ cho hành khách hiện tại ghi thêm nơi họ đang hướng tới. Những trang mới nhanh chóng đầy lên bằng nét chữ đủ kiểu: về thăm mẹ, đi tìm việc, quay lại thăm một người bạn. Sân ga không còn là nơi đợi chuyến tàu cũ, mà là chỗ mọi người bắt đầu đặt tên cho hành trình của mình."),
            E(4, "Mái hiên chung", 3, "Chuyến tàu sẽ dừng", "Một năm sau, bảng điện tử bất ngờ hiện lên dòng chữ “Sân số bốn” dù tuyến tàu ấy vẫn chưa được mở lại. Không ai biết đó là lỗi kỹ thuật hay một lời nhắc. Minh và Hạ đặt chiếc ô xanh dưới mái hiên, bên cạnh cuốn sổ chuyến đi đã có hàng trăm dòng mới.\n\nMột chuyến tàu chậm dừng lại ngoài đường ray phụ để đón người bị lỡ chuyến. Không có tiếng chuông báo, chỉ có cánh cửa mở ra và bác lái tàu vẫy tay. Hạ bước lên trước, Minh theo sau. Mái hiên vẫn ở lại, sẵn sàng che mưa cho người tiếp theo.")
        ]),
        new("Kẻ giữ ngọn hải đăng", [
            E(1, "Ánh đèn trở lại", 2, "Cửa kính mờ muối", "Đêm đầu tiên sau khi ngọn đèn sáng lại, An lau lớp muối bám trên cửa kính và thấy một vệt sáng khác ngoài khơi. Nó không nhấp nháy theo nhịp của tàu cá, cũng không giống đèn phao. Mỗi lần An quay bánh răng, ánh sáng ấy lại dịch gần hơn một chút.\n\nTrong sổ trực của cha, có một trang bị xé khỏi gáy. Chỉ còn câu cuối: “Nếu có ai trả lời, đừng dùng tín hiệu thứ ba.” An chưa từng nghe về quy ước ấy. Anh gọi đài ven biển nhưng chỉ nhận được tiếng nhiễu và một giọng nói lặp lại tên hòn đảo đã biến mất khỏi hải đồ."),
            E(1, "Ánh đèn trở lại", 3, "Tín hiệu ngắn và dài", "An ghi lại nhịp chớp từ biển suốt ba giờ, rồi nhận ra nó là một thông điệp cũ dùng trong thời chiến. Câu trả lời chỉ có thể đến từ một trạm phát đã bị bỏ hoang. Sáng hôm sau, anh tìm thấy vết giày ướt dẫn từ cầu thang hải đăng tới căn phòng khóa kín.\n\nChiếc máy vô tuyến bên trong vẫn còn ấm. Trên bàn có bản đồ đánh dấu một vùng nước nông nơi tàu thường tránh đi. An hiểu cha mình từng giữ liên lạc với ai đó ngoài khơi, nhưng chưa bao giờ ghi lại trong sổ trực. Anh cất chiếc máy vào túi và chờ tín hiệu tiếp theo."),
            E(2, "Tín hiệu từ biển", 2, "Con tàu không có số hiệu", "Con tàu xuất hiện lúc thủy triều rút, mắc cạn trên dải đá ngầm mà mọi hải đồ đều bỏ trống. Thân tàu không có tên, chỉ có một ký hiệu được sơn dưới lớp rong biển. An cùng đội cứu hộ lên boong và tìm thấy những chiếc radio đã tắt từ lâu.\n\nTrong khoang lái có nhật ký của một thủy thủ viết rằng họ đi tìm đảo của những người mất tích. Chuyến đi bị đứt liên lạc trước khi đến nơi. An mang nhật ký về hải đăng, nhưng trang cuối cùng ghi ngày tháng trùng với đêm cha anh biến mất."),
            E(2, "Tín hiệu từ biển", 3, "Người trên bãi đá", "Một cô gái đứng trên bãi đá khi An quay lại con tàu. Cô tự giới thiệu là Linh, người đã sống ở đảo nhỏ ngoài luồng tàu hàng. Linh nói hải đăng là thứ duy nhất họ nhìn thấy trong những tháng biển động, nhưng ánh đèn đã tắt trước khi cô kịp báo tin có người bị thương.\n\nAn nhận ra cha từng dùng những tín hiệu riêng để báo thời tiết cho đảo. Anh không biết vì sao mọi dấu vết bị xóa, chỉ biết họ cần sửa máy phát trước kỳ triều cường. Linh đưa anh một viên đá có khắc ký hiệu, chứng minh hòn đảo vẫn có người chờ ở đó."),
            E(3, "Đêm không trăng", 2, "Ngọn đèn thứ hai", "Không có trăng, biển tối đến mức đường chân trời biến mất. An bật đèn chính, còn Linh mang chiếc đèn dầu nhỏ lên ban công phía đông. Hai nguồn sáng tạo thành một góc hẹp, đủ để một con thuyền lách qua bãi đá.\n\nTừ đảo xa, một ánh đèn đáp lại ba lần. Linh nhận ra nhịp ấy là lời báo rằng người bệnh đã an toàn. An nhìn chiếc đèn nhỏ của cha được dùng lần đầu sau nhiều năm và hiểu vì sao ông không ghi tên hòn đảo trong sổ. Có những con đường chỉ tồn tại để đưa ai đó về nhà."),
            E(3, "Đêm không trăng", 3, "Người giữ đèn mới", "An không rời hải đăng sau đêm ấy. Anh và Linh sửa lại hệ thống tín hiệu, để ánh sáng có thể hướng tới cả luồng tàu lớn lẫn bãi đá nhỏ. Những thủy thủ đi qua bắt đầu nhận ra một nhịp chớp phụ ở phía đông.\n\nTrong ngăn kéo của cha, An tìm được trang nhật ký bị xé. Ông viết rằng đã chọn im lặng để giữ hòn đảo ngoài những cuộc tranh chấp trên đất liền. An không biết có đồng ý với lựa chọn ấy hay không, nhưng anh để lại tên đảo trong bản ghi mới và trao một bản cho Linh. Ngọn đèn vẫn sáng, giờ đây không còn là bí mật của một người."),
            E(4, "Bản đồ những hải trình", 1, "Tên đảo trên hải đồ", "Linh đưa An tới căn phòng cộng đồng trên đảo, nơi những người lớn tuổi vẽ lại đường đi giữa các bãi đá bằng than củi. Mỗi người nhớ một lối khác nhau, bởi dòng chảy thay đổi theo mùa. An mang bản sao nhật ký của cha, bổ sung những nơi từng được đánh dấu bằng tín hiệu đèn.\n\nHọ thống nhất rằng bản đồ mới sẽ ghi cả những lối nguy hiểm lẫn nơi trú bão, không xóa tên đảo khỏi hải đồ nữa. Người giữ đèn không thể thay biển lặng, nhưng có thể giúp thuyền biết mình đang ở đâu."),
            E(4, "Bản đồ những hải trình", 2, "Ca trực lúc bình minh", "Linh bắt đầu thay An trực đèn vào một buổi sáng biển yên. Cô không muốn chỉ làm người nhận tín hiệu; cô học cách bảo dưỡng bánh răng, ghi giờ thủy triều và nhận ra tiếng máy phát sắp hỏng. An dạy cô nhịp chớp cũ, còn Linh sáng tạo thêm một nhịp báo người cần cứu hộ.\n\nKhi một con thuyền nhỏ mất động cơ ngoài khơi, Linh gửi tín hiệu mới. Đội cứu hộ tới kịp trước khi nước lớn. Trong sổ trực, An viết tên cô cạnh tên cha mình, không phải như người thay thế mà như người đầu tiên cùng giữ ngọn đèn."),
            E(4, "Bản đồ những hải trình", 3, "Tín hiệu mở", "Một buổi tối, hải đăng phát đi tín hiệu mở đầu tiên tới tất cả tàu đi ngang: đảo có người ở và sẵn sàng trợ giúp. An biết điều đó có thể khiến nhiều người tìm tới, cả người tốt lẫn kẻ muốn chiếm lấy bờ đá. Linh vẫn chọn gửi, sau khi cả đảo cùng bàn bạc và đồng ý.\n\nTừ ban công, họ nhìn thấy một chiếc thuyền trả lời bằng ánh đèn vàng. Không ai biết ai đang ở trên đó, nhưng lần này tín hiệu không mang theo bí mật hay lời cảnh báo. Nó chỉ nói rằng ngoài biển rộng, có một nơi đã quyết định không còn im lặng.")
        ]),
        new("Vườn thư gửi mai sau", [
            E(1, "Lá thư trong chậu đất", 2, "Hạt giống giấy", "Lá thư được gấp quanh một gói hạt giống nhỏ, nằm sâu dưới chậu bạc hà của bà. An Nhiên nhận ra nét chữ của mẹ nhưng không hiểu vì sao thư lại được chôn ở đó. Dòng đầu viết: “Gửi người sẽ chăm khu vườn này khi mẹ không còn ở đây.”\n\nCô gieo hạt vào luống đất trống và chờ. Vài ngày sau, một mầm cây mảnh khảnh nhú lên, trên lá có vệt trắng như đường gân giấy. Nhiên tìm thêm trong các chậu khác và phát hiện mỗi gói hạt đều đi kèm một bức thư, được ghi ngày gửi cách nhau đúng một năm."),
            E(1, "Lá thư trong chậu đất", 3, "Lịch tưới nước", "Cuốn lịch treo trong nhà kính có những ô ngày được đánh dấu bằng màu khác nhau. Nhiên nghĩ đó là lịch tưới, cho đến khi cô so chúng với ngày mở thư. Mỗi vệt màu dẫn tới một chậu cây chưa từng ra hoa.\n\nBác làm vườn nói mẹ cô thường nhờ ông trộn đất từ nhiều nơi, nhưng không bao giờ giải thích. Khi Nhiên đào chậu cuối cùng, cô tìm thấy tấm vé xe buýt đi tới một ngôi làng ven sông. Mặt sau ghi: “Khi cây này nở, hãy mang theo một lá thư.”"),
            E(2, "Ngày nắng lên", 2, "Khu vườn của hàng xóm", "Nhiên mang những chậu cây nhỏ tới nhà hàng xóm, mong tìm người nhận các lá thư còn lại. Mỗi người nhận ra một phần ký ức của mẹ cô: người từng được giúp dọn nhà, người được tặng giống hoa, người đã cùng bà chăm một khu đất bỏ hoang.\n\nNhững bức thư không kể một bí mật lớn. Chúng chỉ nhắc lại những việc bình thường mà người ta dễ quên: một bữa cơm để dành, chiếc áo được khâu lại, lời hỏi thăm vào ngày mưa. Nhiên gom các câu chuyện thành cuốn sổ, còn khu vườn bắt đầu có thêm nhiều bàn tay chăm sóc."),
            E(2, "Ngày nắng lên", 3, "Cành hoa đầu tiên", "Cây con đầu tiên nở hoa sau một đêm gió mạnh. Nhiên định chụp ảnh gửi cho người bạn thân ở xa, nhưng chợt nhận ra điện thoại của mình đã cũ và danh bạ của mẹ còn lưu một số chưa từng gọi. Cô gọi thử, đầu dây bên kia là một người phụ nữ sống ở ngôi làng ven sông.\n\nNgười phụ nữ ấy giữ một cuốn sổ giống hệt của mẹ Nhiên. Họ hẹn gặp nhau vào cuối tuần, mang theo những bức thư còn thiếu. Cành hoa được cắt một nhánh, cắm vào lọ nhỏ đặt trước cửa nhà kính để ai đi ngang cũng biết khu vườn đang đón khách."),
            E(3, "Lời nhắn cho ngày mai", 2, "Bưu thiếp từ bờ sông", "Ở ngôi làng ven sông, Nhiên gặp bà Thu, người từng học cùng mẹ cô. Bà trao lại những bức thư không được gửi vì mẹ Nhiên muốn chờ khu vườn đủ lớn. Trong đó có một tấm bưu thiếp dành cho chính Nhiên, viết bằng nét chữ mềm mà cô vẫn nhớ.\n\nMẹ viết rằng khu vườn không cần phải giữ nguyên hình dáng ban đầu. Nếu Nhiên muốn trồng rau thay cho hoa, hay nhường luống đất cho người khác, đó vẫn là cách tiếp tục câu chuyện. Cô mang một túi đất từ bờ sông về, đặt cạnh những hạt giống mới và bắt đầu viết thư của riêng mình."),
            E(3, "Lời nhắn cho ngày mai", 3, "Những người cùng gieo", "Ngày hội làm vườn đầu tiên chỉ có sáu người đến, nhưng mỗi người mang theo một loại hạt và một câu chuyện. Trẻ con đặt tên cho các luống cây, còn bác làm vườn hướng dẫn cách giữ nước qua mùa khô. Nhiên dành một góc nhỏ làm hộp thư, nơi ai cũng có thể để lại lời nhắn cho người chăm vườn tiếp theo.\n\nKhi trời tối, cô khóa nhà kính nhưng để chiếc chìa khóa ở chỗ quen thuộc. Trong cuốn sổ mới, Nhiên ghi ngày gieo hạt và tên những người tham gia. Khu vườn không còn là món quà được chôn kín của mẹ; nó trở thành lời hẹn mở, được viết tiếp mỗi mùa."),
            E(4, "Mùa quả đầu tiên", 1, "Luống cây của An Nhiên", "Nhiên dành một luống riêng để trồng những hạt giống cô tự chọn, không gắn với lá thư nào của mẹ. Ban đầu cô sợ mình đang rời xa ký ức, nhưng bác làm vườn nhắc rằng hạt mới không xóa cây cũ. Chúng chỉ khiến khu vườn có thêm một mùa khác.\n\nCô trồng cà chua bên cạnh hoa cúc, ghi rõ ngày gieo và lượng nước. Những người hàng xóm góp phân ủ, còn trẻ con đặt một tấm bảng ghi “luống của Nhiên”. Lần đầu tiên, cô nhìn khu vườn như một nơi mình đang sống chứ không chỉ là món đồ được giao lại."),
            E(4, "Mùa quả đầu tiên", 2, "Bàn dài dưới giàn nho", "Khi cà chua chín, Nhiên kê một chiếc bàn dài dưới giàn nho và mời mọi người mang món ăn tới. Bà Thu kể chuyện mẹ cô từng thất bại với luống rau đầu tiên, còn bác làm vườn thú nhận từng nhổ nhầm cả hàng cây non. Họ ghi những sai lầm ấy vào cuốn sổ để người sau khỏi lặp lại.\n\nBuổi ăn kéo dài tới khi trời nhá nhem. Không ai gửi thư hôm ấy, cũng không ai nhắc chuyện cũ. Nhiên nhận ra việc chăm vườn có thể tạo ra ký ức mới mà không cần xin phép quá khứ."),
            E(4, "Mùa quả đầu tiên", 3, "Hạt giống cho người đến sau", "Cuối mùa, Nhiên thu lại hạt từ những quả cà chua đầu tiên và đặt chúng trong phong bì giấy. Cô viết hướng dẫn trồng ở mặt ngoài, còn bên trong chỉ ghi lời chúc cho người nhận. Một em bé mới chuyển tới chọn phong bì đầu tiên và xin được chăm luống vào mùa tới.\n\nNhiên trao em chiếc bay làm vườn cũ của mẹ, rồi giữ lại một nắm hạt cho mình. Trong hộp thư, cô đặt lá thư đầu tiên do chính tay viết: “Nếu bạn đọc được dòng này, khu vườn vẫn đang lớn.”")
        ]),
        new("Thành phố không ngủ", [
            E(1, "Nửa đêm không tiếng chuông", 2, "Đồng hồ đứng ở mười hai", "Tất cả đồng hồ trong khu phố cùng dừng ở mười hai giờ mười bảy phút. Hà Lam phát hiện điều đó khi chuông nhà thờ im bặt giữa tiếng gió. Trên màn hình điện thoại, thời gian vẫn trôi, nhưng mọi bảng giờ ngoài đường đều giữ nguyên một con số.\n\nNgười bán hàng đêm nói chuyện này từng xảy ra vào ngày thành phố đổi tên một con phố cũ. Lam kiểm tra dữ liệu lưu trữ và tìm thấy hàng trăm bức ảnh chụp cùng một khoảng thời gian. Trong mỗi bức, ở phía xa đều có một người đứng quay lưng về phía máy ảnh."),
            E(1, "Nửa đêm không tiếng chuông", 3, "Bản ghi âm dưới cầu", "Dưới cây cầu đá, Lam tìm thấy một máy ghi âm bọc kín trong túi vải. Băng cũ phát ra tiếng chuông bị bóp nghẹt, sau đó là giọng một đứa trẻ đọc danh sách các con phố. Một cái tên được lặp lại ba lần nhưng không còn xuất hiện trên bản đồ thành phố.\n\nLam hỏi người trông cầu, ông chỉ vào bức tường mới xây bên kia sông. Sau lớp gạch ấy là lối dẫn tới trạm đồng hồ cũ, nơi hệ thống chuông từng được điều khiển bằng tay. Có ai đó đã tháo chiếc búa đồng ra khỏi cơ cấu và để lại dấu vân tay còn nguyên bụi."),
            E(2, "Những con đường lặp lại", 2, "Ngã rẽ không có biển", "Con phố đưa Lam trở lại đúng ngã tư dù cô đi theo bất kỳ hướng nào. Mỗi lần vòng lại, một cửa tiệm biến mất và một căn nhà khác xuất hiện. Cô đánh dấu tường bằng phấn, nhưng dấu vết tự chuyển sang mặt bên kia con đường.\n\nMột cậu giao báo tên Phúc biết lối đi chỉ hiện khi người ta mang theo thứ mình định trả lại. Lam nghĩ tới chiếc đồng hồ bỏ túi của ông nội, món đồ cô giữ từ ngày ông mất. Khi cô đặt nó trên bậc cửa, con đường mở ra phía sau nhà hát đã đóng cửa từ lâu."),
            E(2, "Những con đường lặp lại", 3, "Người sửa bản đồ", "Trong nhà hát, Lam gặp bà Hạnh đang vẽ lại bản đồ thành phố trên những tấm rèm sân khấu. Bà từng là người phụ trách ghi tên đường, nhưng bị buộc nghỉ khi khu phố cũ được quy hoạch lại. Bà giữ bản đồ nguyên gốc dưới sàn gỗ.\n\nBản đồ có một khoảng trắng lớn, nơi dòng sông từng uốn qua khu dân cư. Người ta lấp dòng sông để xây đường, nhưng không ai chuyển tên những con hẻm cũ. Lam hiểu thành phố đang lặp lại lối đi vì nó không biết phải gọi nơi ấy bằng cái tên nào."),
            E(3, "Quảng trường ký ức", 2, "Bức tượng quay mặt", "Bức tượng ở quảng trường luôn quay mặt về phía nhà hát, dù người qua đường khẳng định nó từng nhìn ra sông. Lam tìm thấy dấu xoay ở bệ đá và một chiếc chìa khóa kẹt trong khe hẹp. Phúc nhận ra chìa khóa mở tủ thư cũ ở bưu điện.\n\nTrong tủ là những lá thư chưa từng được phát, tất cả gửi tới những con phố đã bị đổi tên. Có thư của người đi xa, có thư của người chỉ sống cách đó vài dãy nhà. Lam đọc từng địa chỉ và ghi chúng lên bản đồ mới, để những lối đi biến mất có thể được tìm thấy bằng lời gọi cũ."),
            E(3, "Quảng trường ký ức", 3, "Tiếng chuông trở về", "Lam và Phúc đưa chiếc búa đồng trở lại trạm chuông. Họ không thể khôi phục mọi thứ như cũ, nên bà Hạnh đề nghị gọi tên từng con phố trước khi đánh chuông. Người dân đứng kín quảng trường, mỗi người đọc lên một địa chỉ mình còn nhớ.\n\nKhi chuông vang, đồng hồ nhích thêm một phút. Những bảng tên cũ không xuất hiện lại, nhưng con đường thôi dẫn mọi người quay vòng. Lam giữ bản đồ trong thư viện thành phố, kèm ghi chú về những tên gọi đã mất. Đêm ấy, thành phố vẫn thức, nhưng lần đầu tiên nó biết mình đang đi đâu."),
            E(4, "Thành phố ghi nhớ", 1, "Tấm bảng tên phố", "Sáng hôm sau, hội đồng khu phố hỏi Lam có thể trả lại tên cũ cho các con đường hay không. Cô nói mình không thể quyết định thay những người từng sống ở đó. Phúc đề nghị dựng một tấm bảng song ngữ: tên hiện tại ở mặt trước, tên cũ ở mặt sau, cùng lời kể của cư dân.\n\nHọ đi xin ý kiến từng nhà, kể cả những người mới chuyển tới. Có người muốn giữ tên mới, có người nhớ con hẻm bằng một biệt danh chưa từng xuất hiện trên giấy tờ. Tấm bảng dần đầy lên, không có một giọng nói nào lấn át giọng còn lại."),
            E(4, "Thành phố ghi nhớ", 2, "Bản đồ trong thư viện", "Lam trao bản đồ cho thư viện thành phố, nhưng yêu cầu đặt nó trong phòng đọc mở chứ không khóa trong kho lưu trữ. Người dân có thể sửa thông tin, ghi ngày tháng và nộp thêm ảnh cũ. Bà Hạnh trở thành người hướng dẫn nhóm học sinh ghi lại lời kể của người lớn tuổi.\n\nPhúc tìm được một bức ảnh chụp con sông trước khi bị lấp, còn Lam thêm nó vào góc bản đồ. Cô không cố lấp đầy mọi khoảng trắng. Một số nơi chỉ có thể được nhớ bằng cách người ta gọi nhau về nhà."),
            E(4, "Thành phố ghi nhớ", 3, "Đêm không lạc đường", "Nhiều tháng sau, Lam đi bộ qua khu phố lúc nửa đêm và nhận ra mình không còn phải nhìn đồng hồ để tìm đường về. Những con phố vẫn đổi khác, vài cửa tiệm đã đóng, nhưng trên tường có những tấm bảng ghi tên cũ cùng câu chuyện ngắn của người từng sống ở đó.\n\nTiếng chuông vang lên lúc mười hai giờ mười bảy phút, lần này đúng giờ. Phúc đứng ngoài thư viện vẫy cô, trên tay là một bản đồ mới do học sinh vẽ. Lam gấp bản đồ bỏ túi, bước về phía quảng trường. Thành phố vẫn thức, nhưng không còn sợ bị lãng quên.")
        ])
    ];

    public static async Task SeedAsync(ApplicationDbContext context, CancellationToken cancellationToken = default)
    {
        var now = DateTime.UtcNow;
        if (!await context.SubscriptionPlans.AnyAsync(item => item.IsAvailable, cancellationToken))
        {
            context.SubscriptionPlans.AddRange(
                new SubscriptionPlan { Name = "Thư viện 30 ngày", Price = 49000m, DurationDays = 30, AccessScope = "AllStories", IsAvailable = true, CreatedAt = now },
                new SubscriptionPlan { Name = "Thư viện 90 ngày", Price = 119000m, DurationDays = 90, AccessScope = "AllStories", IsAvailable = true, CreatedAt = now });
        }
        foreach (var seed in Stories)
        {
            var story = await context.Stories.SingleOrDefaultAsync(item => item.Title == seed.Title, cancellationToken);
            if (story is null) continue;
            if (story.Title == "Vườn thư gửi mai sau") { story.AccessType = "Mixed"; story.Price = 14900m; story.FreeChapterCount = 2; }
            if (story.Title == "Thành phố không ngủ") { story.AccessType = "Paid"; story.Price = 19900m; story.FreeChapterCount = 0; }
            var groups = await context.StoryChapters.Where(item => item.StoryId == story.Id).ToDictionaryAsync(item => item.Number, cancellationToken);
            var nextSequence = await context.Chapters.Where(item => item.StoryId == story.Id).MaxAsync(item => (int?)item.Number, cancellationToken) ?? 0;
            foreach (var episodeSeed in seed.Episodes)
            {
                if (!groups.TryGetValue(episodeSeed.Chapter, out var group))
                {
                    group = new StoryChapter { StoryId = story.Id, Number = episodeSeed.Chapter, Title = episodeSeed.ChapterTitle };
                    context.StoryChapters.Add(group);
                    groups.Add(episodeSeed.Chapter, group);
                }
                else if (episodeSeed.Chapter > 3 && group.Title != episodeSeed.ChapterTitle)
                {
                    group.Title = episodeSeed.ChapterTitle;
                }

                var exists = await context.Chapters.AnyAsync(item => item.StoryChapterId == group.Id && item.EpisodeNumber == episodeSeed.Episode, cancellationToken);
                if (exists) continue;
                nextSequence++;
                context.Chapters.Add(new Chapter
                {
                    StoryId = story.Id,
                    StoryChapter = group,
                    Number = nextSequence,
                    EpisodeNumber = episodeSeed.Episode,
                    Title = episodeSeed.Title,
                    Content = episodeSeed.Content,
                    IsFree = story.AccessType == "Mixed" && story.FreeChapterCount >= nextSequence,
                    PublishAt = now.AddDays(-Stories.Length - episodeSeed.Chapter),
                    ViewCount = 0
                });
                story.UpdatedAt = now;
            }
        }
        await context.SaveChangesAsync(cancellationToken);
    }

    private static EpisodeSeed E(int chapter, string chapterTitle, int episode, string title, string content) => new(chapter, chapterTitle, episode, title, content);
}
